    "document.getElementById(\042zo\042).onclick = () => setZoom(zi + 1);     // zoom out: more seconds across\012"
    "document.getElementById(\042zi\042).onclick = () => setZoom(zi - 1);\012"
    "document.getElementById(\042grid\042).onchange = e => showGrid = e.target.checked;\012"
    "setZoom(zi);\012"
    "\012"
    "// ---- which decks are shown (1, 2, 3 or 4) and whether the SELECT controls are on, remembered in this browser\012"
    "let shown = [true, true, true, true];\012"
    "try { const q = JSON.parse(localStorage.getItem(\042rxshown\042)); if (Array.isArray(q) && q.length === 4 && q.some(Boolean)) shown = q.map(Boolean); } catch (e) {}\012"
    "const zoomBtn = document.getElementById(\042zoombtn\042);\012"
    "let zoomOn = false; try { zoomOn = localStorage.getItem(\042rxzm\042) === \0421\042; } catch (e) {}\012"
    "const selBtn = document.getElementById(\042select\042), whBox = document.getElementById(\042wh\042);\012"
    "let selOn = false; try { selOn = localStorage.getItem(\042rxsel\042) === \0421\042; } catch (e) {}\012"
    "try { if (localStorage.getItem(\042rxwheel\042) === \0421\042) whBox.checked = true; } catch (e) {}\012"
    "function applyLayout() {\012"
    "  const n = shown.filter(Boolean).length;\012"
    "  decks.forEach((d, i) => d.el.classList.toggle(\042off\042, !shown[i]));\012"
    "  document.querySelectorAll(\042#pick button\042).forEach((b, i) => b.classList.toggle(\042picked\042, shown[i]));\012"
    "  document.querySelectorAll(\042#count button\042).forEach(b => b.classList.toggle(\042picked\042, +b.dataset.n === n));\012"
    "  document.body.classList.toggle(\042select\042, selOn); selBtn.classList.toggle(\042on\042, selOn);\012"
    "  document.body.classList.toggle(\042zoom\042, zoomOn); zoomBtn.classList.toggle(\042on\042, zoomOn);\012"
    "  document.body.classList.toggle(\042wheels\042, whBox.checked);\012"
    "  const lh = Math.floor(root.clientHeight / n); root.style.setProperty(\042--lh\042, lh + \042px\042);    // text and buttons scale with the lane height\012"
    "  try { localStorage.setItem(\042rxshown\042, JSON.stringify(shown)); } catch (e) {}\012"
    "}\012"
    "document.querySelectorAll(\042#count button\042).forEach(b => b.onclick = () => { const n = +b.dataset.n; shown = [0, 1, 2, 3].map(i => i < n); applyLayout(); });\012"
    "document.querySelectorAll(\042#pick button\042).forEach((b, i) => b.onclick = () => { const t = shown.slice(); t[i] = !t[i]; if (t.some(Boolean)) { shown = t; applyLayout(); } });\012"
    "const fsBtn = document.getElementById(\042fsbtn\042);\012"
    "fsBtn.onclick = () => { const de = document.documentElement; try { if (document.fullscreenElement || document.webkitFullscreenElement) (document.exitFullscreen || document.webkitExitFullscreen).call(document); else (de.requestFullscreen || de.webkitRequestFullscreen).call(de); } catch (e) {} };\012"
    "document.addEventListener(\042fullscreenchange\042, () => fsBtn.classList.toggle(\042on\042, !!document.fullscreenElement));\012"
    "zoomBtn.onclick = () => { zoomOn = !zoomOn; for (const d of decks) d.zkey = null; try { localStorage.setItem(\042rxzm\042, zoomOn \077 1 : 0); } catch (e) {} applyLayout(); };\012"
    "selBtn.onclick = () => { selOn = !selOn; try { localStorage.setItem(\042rxsel\042, selOn \077 1 : 0); } catch (e) {} applyLayout(); };\012"
    "whBox.onchange = () => { try { localStorage.setItem(\042rxwheel\042, whBox.checked \077 1 : 0); } catch (e) {} applyLayout(); };\012"
    "window.addEventListener(\042resize\042, applyLayout);\012"
    "if (window.ResizeObserver) new ResizeObserver(applyLayout).observe(root);\012"
    "applyLayout();\012"
    "\012"
    "// ---- touching a lane: the engine decides what it does. SPIN lane: vinyl = touch holds + drag scratches, CDJ = drag nudges.\012"
    "// PITCH lane: drag sideways = tempo (the lane's full width = 16 %, right = faster), double tap = pitch back to 0.\012"
    "for (const d of decks) {\012"
    "  const c = d.main, n = d.i + 1;\012"
    "  try { if (localStorage.getItem(\042rxlane\042 + n) === \042pitch\042) d.lane = \042pitch\042; } catch (x) {}\012"
    "  const paintLane = () => { d.laneBtn.textContent = d.lane === \042pitch\042 \077 \042PITCH\042 : \042SPIN\042; d.laneBtn.classList.toggle(\042pitch\042, d.lane === \042pitch\042); c.classList.toggle(\042pitch\042, d.lane === \042pitch\042); };\012"
    "  d.laneBtn.addEventListener(\042click\042, e => { d.lane = d.lane === \042pitch\042 \077 \042spin\042 : \042pitch\042; try { localStorage.setItem(\042rxlane\042 + n, d.lane); } catch (x) {} paintLane(); });\012"
    "  paintLane();\012"
    "  let lastTap = 0;\012"
    "  c.addEventListener(\042pointerdown\042, e => {\012"
    "    if (d.drag !== null) return;\012"
    "    d.drag = e.pointerId; d.lx = e.clientX; try { c.setPointerCapture(e.pointerId); } catch (x) {} c.classList.add(\042drag\042);\012"
    "    if (d.lane === \042pitch\042) {\012"
    "      send(\042Q \042 + n);\012"
    "      const t = performance.now(); if (t - lastTap < 350) send(\042B \042 + n + \042 rate_set_default 1\042);\012"
    "      lastTap = t;\012"
    "    } else send(\042D \042 + n);\012"
    "    e.preventDefault();\012"
    "  });\012"
    "  c.addEventListener(\042pointermove\042, e => {\012"
    "    if (d.drag !== e.pointerId) return;\012"
    "    const dx = e.clientX - d.lx; d.lx = e.clientX;\012"
    "    if (!dx) return;\012"
    "    const W = c.getBoundingClientRect().width || 1;\012"
    "    if (d.lane === \042pitch\042) { send(\042P \042 + n + \042 \042 + (dx / W * 0.16).toFixed(5)); e.preventDefault(); return; }\012"
    "    const rev = -(dx / W * ZOOMS[zi]) / SEC_PER_REV;       // content follows the finger: drag left = forward in time\012"
    "    send(\042M \042 + n + \042 \042 + rev.toFixed(5));\012"
    "    e.preventDefault();\012"
    "  });\012"
    "  const up = e => { if (d.drag !== e.pointerId) return; d.drag = null; c.classList.remove(\042drag\042); if (d.lane !== \042pitch\042) send(\042U \042 + n); };\012"
    "  c.addEventListener(\042pointerup\042, up); c.addEventListener(\042pointercancel\042, up); c.addEventListener(\042lostpointercapture\042, up);\012"
    "\012"
    "  const wl = d.wheel;                                      // the jog ring: turn it with a finger like the real one\012"
    "  wl.addEventListener(\042pointerdown\042, e => {\012"
    "    if (d.drag !== null) return;\012"
    "    const r = wl.getBoundingClientRect(); d.cx = r.left + r.width / 2; d.cy = r.top + r.height / 2;\012"
    "    d.drag = e.pointerId; d.la = Math.atan2(e.clientY - d.cy, e.clientX - d.cx); try { wl.setPointerCapture(e.pointerId); } catch (x) {} wl.classList.add(\042drag\042);\012"
    "    send(\042D \042 + n); e.preventDefault();\012"
    "  });\012"
    "  wl.addEventListener(\042pointermove\042, e => {\012"
    "    if (d.drag !== e.pointerId) return;\012"
    "    const a = Math.atan2(e.clientY - d.cy, e.clientX - d.cx); let da = a - d.la; d.la = a;\012"
    "    if (da > Math.PI) da -= 2 * Math.PI; if (da < -Math.PI) da += 2 * Math.PI;\012"
    "    if (da) send(\042M \042 + n + \042 \042 + (da / (2 * Math.PI)).toFixed(5));   // clockwise = forward\012"
    "    e.preventDefault();\012"
    "  });\012"
    "  const wup = e => { if (d.drag !== e.pointerId) return; d.drag = null; wl.classList.remove(\042drag\042); send(\042U \042 + n); };\012"
    "  wl.addEventListener(\042pointerup\042, wup); wl.addEventListener(\042pointercancel\042, wup); wl.addEventListener(\042lostpointercapture\042, wup);\012"
    "\012"
    "  d.btn.forEach(b => {\012"
    "    const name = b.dataset.b; if (!name) return;\012"
    "    if (b.dataset.hold) {                                  // CUE: 1 on press, 0 on release, like the hardware\012"
    "      b.addEventListener(\042pointerdown\042, e => { try { b.setPointerCapture(e.pointerId); } catch (x) {} send(\042B \042 + n + \042 \042 + name + \042 1\042); e.preventDefault(); });\012"
    "      const r = () => send(\042B \042 + n + \042 \042 + name + \042 0\042);\012"
    "      b.addEventListener(\042pointerup\042, r); b.addEventListener(\042pointercancel\042, r);\012"
    "    } else if (b.dataset.trig) {\012"
    "      b.addEventListener(\042pointerdown\042, e => { send(\042B \042 + n + \042 \042 + name + \042 1\042); e.preventDefault(); });\012"
    "    } else {\012"
    "      b.addEventListener(\042pointerdown\042, e => { const s = d.s; const cur = !!(s && ({ play: s.pl, sync_master: s.sm, quantize: s.qn, keylock: s.kl, vinyl_mode: s.vin })[name]); send(\042B \042 + n + \042 \042 + name + \042 \042 + (cur \077 0 : 1)); e.preventDefault(); });\012"
    "    }\012"
    "  });\012"
    "}\012"
    "\012"
    "// ---- the ZOOM view: two fingers pinch/drag (or the mouse wheel) like a photo; one finger pans; with SELECT on a tap sends the playhead there\012"
    "const MINSPAN = 1.0;\012"
    "function clampView(d, s) {\012"
    "  const dur = Math.max(1, s.dur);\012"
    "  d.vs = Math.max(Math.min(MINSPAN, dur), Math.min(dur, d.vs));\012"
    "  d.v0 = Math.max(0, Math.min(dur - d.vs, d.v0));\012"
    "}\012"
    "function zoomAt(d, s, tAnchor, fx, factor) {              // keep the time under the finger/cursor (fraction fx of the width) where it is\012"
    "  d.vs *= factor; d.v0 = tAnchor - fx * d.vs; clampView(d, s);\012"
    "}\012"
    "for (const d of decks) {\012"
    "  const c = d.main, n = d.i + 1, pts = new Map();\012"
    "  let tap = null, pinch = null;\012"
    "  c.addEventListener(\042wheel\042, e => {\012"
    "    if (!zoomOn || !d.s || !d.s.ld) return;\012"
    "    e.preventDefault();\012"
    "    const r = c.getBoundingClientRect(), fx = (e.clientX - r.left) / r.width;\012"
    "    zoomAt(d, d.s, d.v0 + fx * d.vs, fx, Math.exp(e.deltaY * 0.0015));\012"
    "  }, { passive: false });\012"
    "  c.addEventListener(\042pointerdown\042, e => {\012"
    "    if (!zoomOn) return;\012"
    "    pts.set(e.pointerId, { x: e.clientX, y: e.clientY });\012"
    "    try { c.setPointerCapture(e.pointerId); } catch (x) {}\012"
    "    if (pts.size === 1) tap = { x: e.clientX, y: e.clientY, t: performance.now(), moved: false };\012"
    "    else { tap = null; const [a, b] = [...pts.values()]; pinch = { dist: Math.hypot(a.x - b.x, a.y - b.y) || 1 }; }\012"
    "    e.stopImmediatePropagation(); e.preventDefault();\012"
    "  }, true);\012"
    "  c.addEventListener(\042pointermove\042, e => {\012"
    "    if (!zoomOn || !pts.has(e.pointerId) || !d.s || !d.s.ld) return;\012"
    "    const r = c.getBoundingClientRect(), p = pts.get(e.pointerId), px = p.x;\012"
    "    p.x = e.clientX; p.y = e.clientY;\012"
    "    if (pts.size >= 2) {                                   // pinch: spread = zoom in, and the middle between the fingers pans\012"
    "      const [a, b] = [...pts.values()], dist = Math.hypot(a.x - b.x, a.y - b.y) || 1, mid = ((a.x + b.x) / 2 - r.left) / r.width;\012"
    "      if (pinch) zoomAt(d, d.s, d.v0 + mid * d.vs, mid, pinch.dist / dist);\012"
    "      if (pinch) pinch.dist = dist;\012"
    "    } else {\012"
    "      if (tap && Math.hypot(e.clientX - tap.x, e.clientY - tap.y) > 8) tap.moved = true;\012"
    "      if (tap && tap.moved) { d.v0 -= (e.clientX - px) / r.width * d.vs; clampView(d, d.s); }\012"
    "    }\012"
    "    e.stopImmediatePropagation(); e.preventDefault();\012"
    "  }, true);\012"
    "  const zup = e => {\012"
    "    if (!zoomOn || !pts.has(e.pointerId)) return;\012"
    "    const r = c.getBoundingClientRect();\012"
    "    if (tap && !tap.moved && pts.size === 1 && performance.now() - tap.t < 450 && selOn && d.s && d.s.ld) {\012"
    "      const t = d.v0 + (e.clientX - r.left) / r.width * d.vs;      // SELECT + ZOOM: a tap puts the playhead there\012"
    "      send(\042G \042 + n + \042 \042 + Math.max(0, Math.min(d.s.dur, t)).toFixed(3));\012"
    "    }\012"
    "    pts.delete(e.pointerId); if (pts.size < 2) pinch = null; if (pts.size === 0) tap = null;\012"
    "    e.stopImmediatePropagation();\012"
    "  };\012"
    "  c.addEventListener(\042pointerup\042, zup, true); c.addEventListener(\042pointercancel\042, zup, true);\012"
    "}\012"
    "</script>\012"
    "</body>\012"
    "</html>\012"
    "\012"
;
